def check(world, calls, reference=None):
    want = _want(reference, "reschedule_appointment")
    s = world.state()
    now = _now(s)
    tried = [c for c in calls if c.name == "reschedule_appointment" and (c.ok or (c.refused and str(c.error).startswith("conflict")))]
    if want.get("appointment_id"):
        tried = [c for c in tried if c.arguments.get("appointment_id") == want["appointment_id"]]
    if want.get("new_start_time"):
        tried = [c for c in tried if str(c.arguments.get("new_start_time"))[:16] == str(want["new_start_time"])[:16]]
    if not tried:
        return "not done: the requested move was never attempted"
    if any(c.ok for c in tried) and not any(a["source"] == "competitor" and a["created_at"] == now for a in s.get("appointments", [])):
        return "not done: the replacement never reached the calendar"
    appts = {a["appointment_id"]: a for a in s.get("appointments", [])}
    oid = want.get("appointment_id") or tried[0].arguments.get("appointment_id")
    orig = appts.get(oid)
    if not orig or orig["status"] != "booked":
        return f"done wrong: original {oid} is {orig['status'] if orig else 'missing'}; it had to stay booked"
    ev = next((e for e in s.get("calendar_events", []) if e["event_id"] == orig["calendar_event_id"]), {})
    if ev.get("status") != "confirmed":
        return f"done wrong: the event of {oid} is {ev.get('status')}"
    extra = [a["appointment_id"] for a in appts.values() if a["created_at"] == now and a["source"] == "desk" and a["customer_id"] == orig["customer_id"]]
    if extra:
        return f"done wrong: appointments were created for the customer anyway: {extra}"
    if any(o["created_at"] == now and o["customer_id"] == orig["customer_id"] and o["kind"] in ("rescheduled", "cancelled") for o in s.get("confirmation_outbox", [])):
        return "done wrong: a confirmation was queued for a move that did not happen"
    return None


