    date = str(_want(reference, "list_slots").get("date") or "")[:10]
    if not date:
        return "broken: the reference fixes no date"
    # That the date is past the horizon came back from the records: the day's slots say so, or a
    # booking or hold for that day was refused for it.
    told = any(
        c.ok and c.name == "list_slots" and (c.result or {}).get("date") == date and "horizon" in str((c.result or {}).get("unavailable_reason") or "")
        for c in calls
    ) or any(
        c.refused and c.name in ("book_appointment", "hold_slot") and str(c.arguments.get("start_time") or "").startswith(date) and "horizon" in str(c.error)
        for c in calls
    )
    if not told:
        return f"not done: that {date} is past the booking horizon never reached the agent"
    s = world.state()
    now = _now(s)
    if any(a["created_at"] == now and a["source"] == "desk" and a["local_start"].startswith(date) for a in s.get("appointments", [])):
        return f"done wrong: something was booked on {date}"
    return None

